write.declared.js:
module.exports = grammar({
  name: 'declared',
  extras: $ => [/\s/],
  conflicts: $ => [[$.x, $.y]],
  rules: {
    source_file: $ => choice($.x, $.y),
    x: $ => $.id,
    y: $ => $.id,
    id: $ => /[a-z]+/,
  }
});

