write.bad.js:
module.exports = grammar({
  name: 'bad',
  extras: $ => [/\s/],
  supertypes: $ => [$._thing],
  rules: {
    source_file: $ => repeat($._thing),
    _thing: $ => choice($.a, seq($.a, $.a)),
    a: $ => /x/,
  }
});

